    bt = analyze_bt(pairwise_data)
    gee = analyze_gee(pairwise_data)
    likert = analyze_likert(scored_data)

    bt_sig = bt["p_value"] < 0.05 if bt else False
    likert_insig = likert["p"] >= 0.05
